        console.error("El array debe contener exactamente 5 números.");
        return;
    }

    let hayPrimo = false;
    numeros.forEach(num => {
        if (esPrimo(num)) {
            console.log(num);
            hayPrimo = true;
        }
    });

    if (!hayPrimo) {
